-- 단계 이동 로그 (선택적: 실제 이메일 발송 이력)
CREATE TABLE IF NOT EXISTS application_stage_log (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  application_id  uuid NOT NULL REFERENCES recruitment_applications(id) ON DELETE CASCADE,
  from_stage      text,
  to_stage        text NOT NULL,
  email_sent      boolean NOT NULL DEFAULT false,
  email_subject   text,
  email_body      text,
  moved_by        uuid REFERENCES auth.users(id),
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_stage_log_app ON application_stage_log(application_id);

ALTER TABLE application_stage_log ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "운영진 이동 이력 조회" ON application_stage_log;
CREATE POLICY "운영진 이동 이력 조회"
ON application_stage_log FOR SELECT
USING (
  EXISTS (
    SELECT 1 FROM recruitment_applications ra
    JOIN recruitments r ON r.id = ra.recruitment_id
    JOIN club_members cm ON cm.club_id = r.club_id
    WHERE ra.id = application_stage_log.application_id
      AND cm.user_id = auth.uid()
      AND cm.role = '운영진'
  )
);

DROP POLICY IF EXISTS "운영진 이동 이력 생성" ON application_stage_log;
CREATE POLICY "운영진 이동 이력 생성"
ON application_stage_log FOR INSERT
WITH CHECK (
  EXISTS (
    SELECT 1 FROM recruitment_applications ra
    JOIN recruitments r ON r.id = ra.recruitment_id
    JOIN club_members cm ON cm.club_id = r.club_id
    WHERE ra.id = application_stage_log.application_id
      AND cm.user_id = auth.uid()
      AND cm.role = '운영진'
  )
);


-- ============================================================
-- source: 20260517400000_recruitment_stats_view.sql
-- ============================================================
-- Step 7: 채용 통계 view
-- RecruitmentsList에서 applicant_count 별도 쿼리하지 않고 한번에 가져오기 위한 view.
-- RLS 는 underlying recruitments 테이블 정책을 따른다.
-- pipeline_stages 는 jsonb 타입이라 jsonb_array_length / ->> 로 접근한다.

DROP VIEW IF EXISTS recruitment_with_counts;

CREATE VIEW recruitment_with_counts
WITH (security_invoker = true)
AS
SELECT
  r.*,
  COALESCE(c.applicant_count, 0)::int AS applicant_count,
  COALESCE(p.passed_count, 0)::int AS passed_count
FROM recruitments r
LEFT JOIN (
  SELECT recruitment_id, COUNT(*) AS applicant_count
  FROM recruitment_applications
  GROUP BY recruitment_id
) c ON c.recruitment_id = r.id
LEFT JOIN LATERAL (
  SELECT COUNT(*) AS passed_count
  FROM recruitment_applications ra
  WHERE ra.recruitment_id = r.id
    AND jsonb_typeof(r.pipeline_stages) = 'array'
    AND jsonb_array_length(r.pipeline_stages) > 0
    AND ra.status = (r.pipeline_stages ->> (jsonb_array_length(r.pipeline_stages) - 1))
) p ON true;

COMMENT ON VIEW recruitment_with_counts IS
  '공고별 총 지원자수·합격자수를 미리 집계한 뷰. RLS는 base recruitments 정책을 따름.';


-- ============================================================
-- source: 20260518000000_member_roster_expansion.sql
-- ============================================================
-- Phase A Step 1: 부원 명단 관리 확장
-- 1) profiles 에 생년월일, 학적상태 추가 (phone/university/major 는 기존 존재)
-- 2) club_members 에 role_function 추가
--    - position (직책: 회장/팀장/팀원) 과 구분
--    - role_function (업무 역할: 기획/디자인/개발/마케팅 등)

-- ─────────────────────────────────────────────────────────────
-- profiles 확장
-- ─────────────────────────────────────────────────────────────
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS birthdate date,
  ADD COLUMN IF NOT EXISTS academic_status text;

-- 학적상태 enum check (NULL 허용)
ALTER TABLE public.profiles
  DROP CONSTRAINT IF EXISTS profiles_academic_status_check;
ALTER TABLE public.profiles
  ADD CONSTRAINT profiles_academic_status_check
  CHECK (academic_status IS NULL OR academic_status IN ('재학','휴학','수료','졸업'));

COMMENT ON COLUMN public.profiles.birthdate IS '생년월일 (운영진 View 전용 노출)';
COMMENT ON COLUMN public.profiles.academic_status IS '학적 상태: 재학/휴학/수료/졸업';

-- ─────────────────────────────────────────────────────────────
-- club_members 확장
-- ─────────────────────────────────────────────────────────────
ALTER TABLE public.club_members
  ADD COLUMN IF NOT EXISTS role_function text;

COMMENT ON COLUMN public.club_members.role_function IS
  '업무 역할(기획/디자인/개발/마케팅 등). position(직책: 회장/팀장)과 구분.';


-- ============================================================
-- source: 20260518100000_session_targets_and_status.sql
-- ============================================================
-- Phase B Step 8-DB: 출석 세션 분리 / 정확한 출석률 모수
-- 1) sessions.target_generations: 대상 기수 목록 (예: {"13기","14기"})
-- 2) session_targets: 세션별 출석 대상 부원 (예외처리된 후) - 출석률 산정 분모
-- 3) attendances.status: '공결' 추가 (출석인정)

-- ─────────────────────────────────────────────────────────────
-- 1) sessions 확장
-- ─────────────────────────────────────────────────────────────
ALTER TABLE public.sessions
  ADD COLUMN IF NOT EXISTS target_generations text[] DEFAULT '{}';

COMMENT ON COLUMN public.sessions.target_generations IS '대상 기수 목록 (예: {"13기","14기"})';

-- ─────────────────────────────────────────────────────────────
-- 2) session_targets 테이블
-- ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.session_targets (
  session_id uuid NOT NULL REFERENCES public.sessions(id) ON DELETE CASCADE,
  member_id  uuid NOT NULL REFERENCES public.club_members(id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, member_id)
);

COMMENT ON TABLE public.session_targets IS
  '출석률 산정 모수: 세션 생성 시 예외처리 후의 출석 대상 부원';

CREATE INDEX IF NOT EXISTS session_targets_session_idx ON public.session_targets(session_id);
CREATE INDEX IF NOT EXISTS session_targets_member_idx  ON public.session_targets(member_id);

ALTER TABLE public.session_targets ENABLE ROW LEVEL SECURITY;

-- SELECT: 해당 클럽의 부원 모두 (자기가 대상인지 확인 가능)
DROP POLICY IF EXISTS "세션 대상자 조회" ON public.session_targets;
CREATE POLICY "세션 대상자 조회" ON public.session_targets
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1
      FROM public.club_members cm
      JOIN public.sessions s ON s.id = session_targets.session_id
      WHERE s.club_id = cm.club_id
        AND cm.user_id = auth.uid()
    )
    OR EXISTS (SELECT 1 FROM public.global_admins WHERE id = auth.uid())
  );

-- INSERT/DELETE: 운영진만
DROP POLICY IF EXISTS "세션 대상자 추가" ON public.session_targets;
CREATE POLICY "세션 대상자 추가" ON public.session_targets
  FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.club_members cm
      JOIN public.sessions s ON s.id = session_targets.session_id
      WHERE s.club_id = cm.club_id
        AND cm.user_id = auth.uid()
        AND cm.role = '운영진'
    )
    OR EXISTS (SELECT 1 FROM public.global_admins WHERE id = auth.uid())
  );

DROP POLICY IF EXISTS "세션 대상자 삭제" ON public.session_targets;
CREATE POLICY "세션 대상자 삭제" ON public.session_targets
  FOR DELETE
  USING (
    EXISTS (
      SELECT 1
      FROM public.club_members cm
      JOIN public.sessions s ON s.id = session_targets.session_id
      WHERE s.club_id = cm.club_id
        AND cm.user_id = auth.uid()
        AND cm.role = '운영진'
    )
    OR EXISTS (SELECT 1 FROM public.global_admins WHERE id = auth.uid())
  );

-- ─────────────────────────────────────────────────────────────
-- 3) attendances.status 에 '공결' 추가
-- ─────────────────────────────────────────────────────────────
ALTER TABLE public.attendances
  DROP CONSTRAINT IF EXISTS attendances_status_check;
ALTER TABLE public.attendances
  ADD CONSTRAINT attendances_status_check
  CHECK (status IN ('출석','지각','결석','공결'));


-- ============================================================
-- source: 20260518110000_sessions_with_counts_view.sql
-- ============================================================
-- Phase B Step 9: 세션별 출석 통계 view
-- AttendanceList 에서 출석률·대상수를 한번에 가져오기 위한 view.
-- RLS 는 underlying sessions 테이블 정책을 따른다.

DROP VIEW IF EXISTS sessions_with_counts;

CREATE VIEW sessions_with_counts
WITH (security_invoker = true)
AS
SELECT
  s.*,
  COALESCE(t.target_count, 0)::int   AS target_count,
  COALESCE(a.attended_count, 0)::int AS attended_count
FROM sessions s
LEFT JOIN (
  SELECT session_id, COUNT(*) AS target_count
  FROM session_targets
  GROUP BY session_id
) t ON t.session_id = s.id
LEFT JOIN (
  SELECT session_id, COUNT(*) AS attended_count
  FROM attendances
  WHERE status = '출석'
  GROUP BY session_id
) a ON a.session_id = s.id;

COMMENT ON VIEW sessions_with_counts IS
  '세션별 출석 대상수·출석 인원 집계. RLS 는 base sessions 정책을 따름.';


-- ============================================================
-- source: 20260518200000_promote_applicant_trigger.sql
-- ============================================================
-- Phase B: 리크루팅 최종합격 → 부원 자동 추가 트리거
-- recruitment_applications.status 가 recruitments.pipeline_stages 의 마지막 단계로 변경되면
-- 해당 user_id 를 club_members 에 자동 insert (이미 있으면 무시).
-- SECURITY DEFINER 로 RLS 우회 (지원자 자신이 club_members 에 insert 권한 없을 수 있음).

CREATE OR REPLACE FUNCTION public.promote_applicant_to_member()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_last_stage text;
  v_club_id    uuid;
BEGIN
  -- 변경 없으면 종료 (UPDATE 시)
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.status IS NULL THEN
    RETURN NEW;
  END IF;

  -- 공고의 최종 stage + club_id 조회
  SELECT
    pipeline_stages ->> (jsonb_array_length(pipeline_stages) - 1),
    club_id
  INTO v_last_stage, v_club_id
  FROM public.recruitments
  WHERE id = NEW.recruitment_id
    AND jsonb_typeof(pipeline_stages) = 'array'
    AND jsonb_array_length(pipeline_stages) > 0;

  -- 최종 stage 일치 시 club_members 에 추가 (중복 방지)
  IF v_last_stage IS NOT NULL
     AND NEW.status = v_last_stage
     AND v_club_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.club_members
      WHERE user_id = NEW.user_id
        AND club_id = v_club_id
    ) THEN
      INSERT INTO public.club_members (user_id, club_id, role, status)
      VALUES (NEW.user_id, v_club_id, '부원', '활동중');
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.promote_applicant_to_member() IS
  '지원자 status 가 공고 파이프라인의 마지막 단계가 되면 자동으로 club_members 에 추가';

DROP TRIGGER IF EXISTS promote_applicant_on_final_status ON public.recruitment_applications;
CREATE TRIGGER promote_applicant_on_final_status
  AFTER INSERT OR UPDATE OF status ON public.recruitment_applications
  FOR EACH ROW
  EXECUTE FUNCTION public.promote_applicant_to_member();


