    }'::jsonb,
    now(), now()
  )
  ;


  RAISE NOTICE '데모 동아리 3종 시드 완료 (codewave: %, frame: %, spike: %)',
    v_codewave_id, v_frame_id, v_spike_id;
END;
$$;


