            { "id": "m2", "name": "박준호", "role": "부회장 · 크리에이티브", "imgSrc": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=600&q=80" },
            { "id": "m3", "name": "이소연", "role": "기획팀장", "imgSrc": "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=600&q=80" },
            { "id": "m4", "name": "최민준", "role": "디자인팀장", "imgSrc": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=600&q=80" }
          ]
        },
        {
          "id": "q1", "type": "quote", "align": "center", "maxWidth": 800,
          "paddingY": 110, "bgColor": "#f0eae2",
          "text": "VIBE에서 보낸 1년이 4년 대학생활 중 가장 밀도 있는 시간이었습니다. 클라이언트 앞에서 브리핑하던 그 경험이 지금의 저를 만들었어요.",
          "fontSize": 26, "textColor": "#0e0e0e", "accentColor": "#b8965a",
          "attribution": "— 23기 김채원, 現 HS애드 브랜드플래너",
          "avatarSrc": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80"
        },
        {
          "id": "faq", "type": "faq", "title": "자주 묻는 질문",
          "iconStyle": "plus", "openBg": "#f0eae2", "borderRadius": 8,
          "items": [
            { "id": "fq1", "question": "디자인 비전공자도 지원 가능한가요?",
              "answer": "네. 전공 무관하게 브랜드·디자인에 관심 있는 누구나 지원 가능합니다. 매 기수 약 절반이 비전공자입니다." },
            { "id": "fq2", "question": "활동 빈도와 회비는?",
              "answer": "매주 목요일 정기 세션 + 프로젝트별 자체 모임. 반기 활동비 50,000원(전시·재료·네트워킹)." },
            { "id": "fq3", "question": "포트폴리오가 필요한가요?",
              "answer": "필수는 아닙니다. 지원 동기와 디자인에 대한 관심을 보여주시면 충분합니다." }
          ]
        },
        {
          "id": "cta", "type": "button", "text": "25기 지원서 작성하기",
          "actionType": "modal", "btnSize": "l",
          "btnBg": "#b8965a", "btnTextColor": "#ffffff",
          "radius": 0, "paddingY": 120, "bgColor": "#faf8f5"
        }
      ]
    }'::jsonb,
    now(), now()
  );

  RAISE NOTICE '엔터프라이즈 동아리 4종 시드 완료 (dev-hustler: %, codewave: %, frame: %, vibe-design: %)',
    v_devhustler_id, v_codewave_id, v_frame_id, v_vibe_id;
END;
$$;


-- ============================================================
-- source: 20260522000000_club_pages_bucket.sql
-- ============================================================
-- club-pages Storage 버킷 생성 (이미 있으면 무시)
-- 용도: 동아리 홈페이지 빌더 이미지(ImageUploader) + 리크루팅 페이지 이미지(RecruitPageBuilder)
--       + 공개 지원서 첨부파일(ClubApply, applications/ 폴더)
-- public 버킷이라 getPublicUrl 로 바로 노출. mime 제한은 클라이언트에서 처리
-- (지원서 첨부는 PDF·문서도 허용해야 하므로 버킷 레벨 mime 제한은 두지 않음).
INSERT INTO storage.buckets (id, name, public, file_size_limit)
VALUES ('club-pages', 'club-pages', true, 10485760)  -- 10MB
ON CONFLICT (id) DO NOTHING;

-- 조회: 누구나 (public bucket)
CREATE POLICY "club-pages 공개 조회"
ON storage.objects FOR SELECT
USING (bucket_id = 'club-pages');

-- 업로드: 누구나 (운영진 빌더 이미지 + 비로그인 지원자 첨부)
CREATE POLICY "club-pages 업로드"
ON storage.objects FOR INSERT
WITH CHECK (bucket_id = 'club-pages');

-- 수정(upsert 덮어쓰기): 로그인 사용자만
CREATE POLICY "club-pages 수정"
ON storage.objects FOR UPDATE
USING (bucket_id = 'club-pages' AND auth.uid() IS NOT NULL);

-- 삭제: 로그인 사용자만
CREATE POLICY "club-pages 삭제"
ON storage.objects FOR DELETE
USING (bucket_id = 'club-pages' AND auth.uid() IS NOT NULL);


-- ============================================================
-- source: 20260602000000_club_page_draft_publish.sql
-- ============================================================
-- ============================================================
-- 1-Page 웹빌더: 초안(draft) / 공개본(published) 분리
--
-- 문제: 지금까지 club_pages.blocks 한 컬럼을 편집 초안과 방문자에게
--       보이는 공개본이 함께 사용 → 자동저장이 곧바로 라이브 페이지를
--       덮어써서 "발행"의 의미가 모호했다.
--
-- 해결: draft 컬럼을 추가해 역할을 분리한다.
--   - draft  : 작업 중인 초안 (자동저장 대상, 방문자에게 노출 안 됨)
--   - blocks : 발행된 공개본 (방문자가 보는 스냅샷, '발행' 시에만 갱신)
--   - published_at : 마지막 발행 시각 (NULL = 아직 발행 안 함 → 기본 소개 페이지 노출)
--
-- 롤백: draft 컬럼만 추가하므로 되돌리려면 `ALTER TABLE club_pages DROP COLUMN draft;`
--       기존 blocks/published_at 의미는 그대로 보존된다(하위 호환).
-- ============================================================

ALTER TABLE public.club_pages
  ADD COLUMN IF NOT EXISTS draft jsonb;

-- 기존 페이지의 현재 내용을 초안의 출발점으로 백필
-- (이미 발행된 페이지는 공개본 == 초안 상태로 시작 → '발행 안 된 변경사항' 없음)
UPDATE public.club_pages
  SET draft = blocks
  WHERE draft IS NULL;


-- ============================================================
-- source: 20260602010000_ops_console_registration_loop.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────
-- 서비스 운영 콘솔 + 동아리 등록 프로세스 루프 닫기
--  1) notifications: 범용 인앱 알림 테이블
--  2) club_registration_requests 상태 변경 → 신청자 알림 트리거
--  3) 보완요청 건의 신청자 본인 재제출(UPDATE) RLS
--  4) reviewed_by 컬럼 (심사 담당자 기록)
--  5) approve_club_registration RPC (clubs+members+status 원자적 승인)
--  6) clubs 마스터 UPDATE 정책 (운영 콘솔 인증 토글용)
-- ─────────────────────────────────────────────────────────────

-- ── 1) 범용 인앱 알림 ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.notifications (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  type        text NOT NULL,            -- 'registration_status' 등
  title       text NOT NULL,
  body        text,
  link        text,                     -- 클릭 시 이동 경로
  is_read     boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

-- 본인 알림만 조회 / 읽음 처리. INSERT 정책 없음 → 트리거(SECURITY DEFINER)로만 생성.
DROP POLICY IF EXISTS "notifications_select_own" ON public.notifications;
CREATE POLICY "notifications_select_own"
  ON public.notifications FOR SELECT
  USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "notifications_update_own" ON public.notifications;
CREATE POLICY "notifications_update_own"
  ON public.notifications FOR UPDATE
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS notifications_user_unread_idx
  ON public.notifications(user_id, is_read, created_at DESC);


-- ── 4) 심사 담당자 기록 ───────────────────────────────────────
ALTER TABLE public.club_registration_requests
  ADD COLUMN IF NOT EXISTS reviewed_by uuid REFERENCES auth.users(id);


-- ── 2) 상태 변경 시 신청자에게 알림 ───────────────────────────
CREATE OR REPLACE FUNCTION public.notify_registration_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- 마스터가 처리하는 상태로 바뀔 때만 알림 (재제출 시의 '검토대기'는 제외)
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('검토중', '보완요청', '승인', '거절') THEN
    INSERT INTO public.notifications (user_id, type, title, body, link)
    VALUES (
      NEW.user_id,
      'registration_status',
      CASE NEW.status
        WHEN '검토중'   THEN NEW.club_name || ' 등록 심사가 시작됐어요'
        WHEN '보완요청' THEN NEW.club_name || ' 등록에 보완 요청이 있어요'
        WHEN '승인'     THEN NEW.club_name || ' 등록이 승인됐어요 🎉'
        WHEN '거절'     THEN NEW.club_name || ' 등록 신청이 반려됐어요'
      END,
      NEW.reviewer_note,
      CASE WHEN NEW.status = '승인' THEN '/admin/dashboard' ELSE '/club-setup' END
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_registration_status ON public.club_registration_requests;
CREATE TRIGGER trg_notify_registration_status
  AFTER UPDATE OF status ON public.club_registration_requests
  FOR EACH ROW EXECUTE FUNCTION public.notify_registration_status();


-- ── 3) 보완요청 건의 신청자 본인 재제출 ──────────────────────
-- 본인 소유 + 현재 '보완요청' 상태인 행만 수정 가능, 수정 후 상태는 '검토대기'로만.
DROP POLICY IF EXISTS "registration_requests_owner_resubmit" ON public.club_registration_requests;
CREATE POLICY "registration_requests_owner_resubmit"
  ON public.club_registration_requests
  FOR UPDATE
  USING (auth.uid() = user_id AND status = '보완요청')
  WITH CHECK (auth.uid() = user_id AND status = '검토대기');


-- ── 5) 원자적 승인 RPC ───────────────────────────────────────
CREATE OR REPLACE FUNCTION public.approve_club_registration(
  p_request_id uuid,
  p_note       text DEFAULT NULL
)
RETURNS text   -- 생성된 동아리 slug
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_req     public.club_registration_requests%ROWTYPE;
  v_club_id uuid;
  v_slug    text;
BEGIN
  -- 마스터만 실행 가능
  IF NOT EXISTS (SELECT 1 FROM public.global_admins WHERE id = auth.uid()) THEN
    RAISE EXCEPTION '권한이 없습니다.';
  END IF;

  SELECT * INTO v_req
  FROM public.club_registration_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION '신청서를 찾을 수 없습니다.'; END IF;
  IF v_req.status = '승인' THEN RAISE EXCEPTION '이미 승인된 신청입니다.'; END IF;

  v_slug := 'club-' || (extract(epoch FROM now()) * 1000)::bigint;

  INSERT INTO public.clubs (slug, name, type, one_line_desc, description, location, is_certified, theme_color)
  VALUES (v_slug, v_req.club_name, v_req.club_type, v_req.one_line_desc, v_req.description, v_req.location, true, '#f97316')
  RETURNING id INTO v_club_id;

  INSERT INTO public.club_members (user_id, club_id, role, status)
  VALUES (v_req.user_id, v_club_id, '운영진', '활동중');

  UPDATE public.club_registration_requests
  SET status      = '승인',
      reviewer_note = COALESCE(p_note, reviewer_note),
      reviewed_by  = auth.uid(),
      reviewed_at  = now()
  WHERE id = p_request_id;

  RETURN v_slug;
END;
$$;

GRANT EXECUTE ON FUNCTION public.approve_club_registration(uuid, text) TO authenticated;


-- ── 6) 마스터의 동아리 수정 권한 (인증 토글 등) ──────────────
DROP POLICY IF EXISTS "clubs_master_update" ON public.clubs;
CREATE POLICY "clubs_master_update"
  ON public.clubs FOR UPDATE
  USING (EXISTS (SELECT 1 FROM public.global_admins WHERE id = auth.uid()));


-- ============================================================
-- source: 20260604000000_notify_applicant_stage_move.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────
-- 지원자 단계 이동 시 인앱 알림 (이메일 발송 대체)
--  운영진이 칸반에서 지원자 단계를 옮기며 "알림 보내기"를 선택하면
--  application_stage_log 에 email_sent=true 로 기록되는데,
--  그 INSERT 를 받아 지원자에게 인앱 notifications 를 생성한다.
--  (이메일 발송 인프라 대신 인앱 알림으로 전 흐름 통일. email_* 컬럼은
--   메시지 저장소로 그대로 재사용 — 추후 이메일 발송 추가 시 동일 데이터 활용.)
-- ─────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.notify_applicant_stage_move()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
  v_title   text;
BEGIN
  -- "알림 보내기"를 선택한 이동만 통지
  IF NOT COALESCE(NEW.email_sent, false) THEN
    RETURN NEW;
  END IF;

  -- 지원자(auth user) 조회
  SELECT user_id INTO v_user_id
  FROM public.recruitment_applications
  WHERE id = NEW.application_id;

  -- 계정 없는 지원(user_id NULL)은 인앱 알림 대상 아님
  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_title := COALESCE(NULLIF(btrim(NEW.email_subject), ''),
                      '지원 상태가 ''' || NEW.to_stage || '''(으)로 변경됐어요');

  INSERT INTO public.notifications (user_id, type, title, body, link)
  VALUES (
    v_user_id,
    'application_status',
    v_title,
    NEW.email_body,
    '/mypage'
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_applicant_stage_move ON public.application_stage_log;
CREATE TRIGGER trg_notify_applicant_stage_move
  AFTER INSERT ON public.application_stage_log
  FOR EACH ROW EXECUTE FUNCTION public.notify_applicant_stage_move();

